55	    sess: Arc<Session>,
56	    turn_context: Arc<TurnContext>,
57	    initial_context_injection: InitialContextInjection,
58	) -> CodexResult<()> {
59	    let prompt = turn_context.compact_prompt().to_string();
60	    let input = vec![UserInput::Text {
61	        text: prompt,
62	        // Compaction prompt is synthesized; no UI element ranges to preserve.
63	        text_elements: Vec::new(),
64	    }];
65	
66	    run_compact_task_inner(sess, turn_context, input, initial_context_injection).await?;
