660	    /// Opportunistically preconnects a websocket for this turn-scoped client session.
661	    ///
662	    /// This performs only connection setup; it never sends prompt payloads.
663	    pub async fn preconnect_websocket(
664	        &mut self,
665	        session_telemetry: &SessionTelemetry,
666	        model_info: &ModelInfo,
667	    ) -> std::result::Result<(), ApiError> {
668	        if !self.client.responses_websocket_enabled(model_info) {
669	            return Ok(());
670	        }
671	        if self.websocket_session.connection.is_some() {
672	            return Ok(());
673	        }
674	
675	        let client_setup = self.client.current_client_setup().await.map_err(|err| {
676	            ApiError::Stream(format!(
677	                "failed to build websocket prewarm client setup: {err}"
678	            ))
679	        })?;
680	
681	        let connection = self
682	            .client
683	            .connect_websocket(
684	                session_telemetry,
685	                client_setup.api_provider,
686	                client_setup.api_auth,
687	                Some(Arc::clone(&self.turn_state)),
688	                None,
689	            )
690	            .await?;
691	        self.websocket_session.connection = Some(connection);
692	        Ok(())
693	    }
694	    /// Returns a websocket connection for this turn.
695	    async fn websocket_connection(
696	        &mut self,
697	        session_telemetry: &SessionTelemetry,
698	        api_provider: codex_api::Provider,
699	        api_auth: CoreAuthProvider,
700	        turn_metadata_header: Option<&str>,
701	        options: &ApiResponsesOptions,
702	    ) -> std::result::Result<&ApiWebSocketConnection, ApiError> {
703	        let needs_new = match self.websocket_session.connection.as_ref() {
704	            Some(conn) => conn.is_closed().await,
705	            None => true,
706	        };
707	
708	        if needs_new {
709	            self.websocket_session.last_request = None;
710	            self.websocket_session.last_response_rx = None;
711	            let turn_state = options
712	                .turn_state
713	                .clone()
714	                .unwrap_or_else(|| Arc::clone(&self.turn_state));
715	            let new_conn = self
716	                .client
717	                .connect_websocket(
718	                    session_telemetry,
719	                    api_provider,
720	                    api_auth,
721	                    Some(turn_state),
722	                    turn_metadata_header,
723	                )
724	                .await?;
725	            self.websocket_session.connection = Some(new_conn);
726	        }
727	
728	        self.websocket_session
729	            .connection
730	            .as_ref()
731	            .ok_or(ApiError::Stream(
732	                "websocket connection is unavailable".to_string(),
733	            ))
734	    }
