756	        session_telemetry: &SessionTelemetry,
757	        effort: Option<ReasoningEffortConfig>,
758	        summary: ReasoningSummaryConfig,
759	        service_tier: Option<ServiceTier>,
760	        turn_metadata_header: Option<&str>,
761	    ) -> Result<ResponseStream> {
