765	                path,
766	                self.client.state.provider.stream_idle_timeout(),
767	            )
768	            .map_err(map_api_error)?;
769	            let (stream, _last_request_rx) = map_response_stream(stream, session_telemetry.clone());
770	            return Ok(stream);
771	        }
772	
773	        let auth_manager = self.client.state.auth_manager.clone();
774	        let mut auth_recovery = auth_manager
775	            .as_ref()
776	            .map(super::auth::AuthManager::unauthorized_recovery);
777	        loop {
778	            let client_setup = self.client.current_client_setup().await?;
779	            let transport = ReqwestTransport::new(build_reqwest_client());
780	            let (request_telemetry, sse_telemetry) =
781	                Self::build_streaming_telemetry(session_telemetry);
