791	                service_tier,
792	            )?;
793	            let client = ApiResponsesClient::new(
794	                transport,
795	                client_setup.api_provider,
796	                client_setup.api_auth,
797	            )
798	            .with_telemetry(Some(request_telemetry), Some(sse_telemetry));
799	            let stream_result = client.stream_request(request, options).await;
800	
801	            match stream_result {
802	                Ok(stream) => {
803	                    let (stream, _) = map_response_stream(stream, session_telemetry.clone());
